<?php
defined('ABSPATH') || exit;
get_header();
$is_product = is_post_type_archive('hpv_product') || is_tax('hpv_category');
$is_project = is_post_type_archive('hpv_project');
$title = $is_product ? (is_tax('hpv_category') ? single_term_title('', false) : 'Sản phẩm & giải pháp') : ($is_project ? 'Ứng dụng cho từng không gian' : get_the_archive_title());
?>
<div class="container"><?php hpv_breadcrumbs(); ?></div><section class="page-intro container"><span class="section-kicker"><?php echo $is_product ? 'Danh mục Hải Phát Vina' : ($is_project ? 'Công trình & gợi ý ứng dụng' : 'Kiến thức & kinh nghiệm'); ?></span><h1><?php echo esc_html($title); ?></h1><p><?php echo $is_product ? 'Tìm hiểu nhóm sản phẩm, trao đổi quy cách và lựa chọn phương án phù hợp với nhu cầu thực tế.' : ($is_project ? 'Khám phá những cách sử dụng mái che và bạt trong đời sống, kinh doanh và sản xuất. Các nội dung minh họa được ghi nhãn riêng.' : esc_html(wp_strip_all_tags(get_the_archive_description()))); ?></p></section>
<section class="section archive-section"><div class="container <?php echo $is_product ? 'catalog-layout' : ''; ?>">
<?php if ($is_product) : ?><aside class="catalog-sidebar"><h2>Nhóm sản phẩm</h2><ul><li><a class="<?php echo is_post_type_archive('hpv_product') && empty($_GET['nhom']) ? 'is-active' : ''; ?>" href="<?php echo esc_url(hpv_products_url()); ?>">Tất cả sản phẩm</a></li><?php $terms = get_terms(array('taxonomy' => 'hpv_category', 'hide_empty' => true)); if (!is_wp_error($terms)) { foreach ($terms as $term) { $active = is_tax('hpv_category', $term->slug); echo '<li><a class="' . ($active ? 'is-active' : '') . '" href="' . esc_url(get_term_link($term)) . '">' . esc_html($term->name) . '<span>' . (int) $term->count . '</span></a></li>'; } } ?></ul><div class="sidebar-help"><?php echo hpv_icon('chat'); ?><h3>Cần chọn vật liệu?</h3><p>Gửi kích thước và mục đích sử dụng để cùng trao đổi.</p><a href="<?php echo esc_url(hpv_phone_url()); ?>"><?php echo esc_html(hpv_get('phone')); ?></a></div></aside><?php endif; ?>
<div class="catalog-content"><?php if ($is_product) : ?><div class="catalog-toolbar"><span><?php echo (int) $wp_query->found_posts; ?> sản phẩm</span><form role="search" method="get" class="catalog-search" action="<?php echo esc_url(home_url('/')); ?>"><label class="sr-only" for="catalog-search">Tìm sản phẩm</label><input id="catalog-search" type="search" name="s" placeholder="Tìm sản phẩm…" value="<?php echo esc_attr(get_search_query()); ?>"><input type="hidden" name="post_type" value="hpv_product"><button type="submit" aria-label="Tìm sản phẩm"><?php echo hpv_icon('search'); ?></button></form></div><?php endif; ?>
<div class="<?php echo $is_product ? 'product-grid product-grid--catalog' : ($is_project ? 'project-grid' : 'article-grid'); ?>"><?php if (have_posts()) { while (have_posts()) { the_post(); get_template_part('template-parts/' . ($is_product ? 'product-card' : ($is_project ? 'project-card' : 'article-card'))); } } else { echo '<div class="empty-state"><h2>Thông tin đang được cập nhật</h2><p>Liên hệ Hải Phát Vina để trao đổi nhu cầu của bạn.</p><a class="button button--navy" href="' . esc_url(hpv_page_url('contact')) . '">Liên hệ tư vấn</a></div>'; } ?></div>
<?php the_posts_pagination(array('mid_size' => 1, 'prev_text' => 'Trang trước', 'next_text' => 'Trang sau')); ?></div></div></section>
<?php get_footer(); ?>
